import java.util.Scanner;

public class PayrollCalculator {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);

        System.out.print("Employee name: ");
        String name = input.nextLine();

        System.out.print("Hours worked: ");
        int hours = input.nextInt();

        System.out.print("Hourly rate: ");
        double rate = input.nextDouble();

        double gross = hours * rate;
        double tax = gross * 0.12;
        double net = gross - tax;

        System.out.println();
        System.out.printf("%-14s %s%n",    "Employee:", name);
        System.out.printf("%-14s %d%n",    "Hours:",    hours);
        System.out.printf("%-14s %.2f%n",  "Rate:",     rate);
        System.out.printf("%-14s %.2f%n",  "Gross pay:", gross);
        System.out.printf("%-14s %.2f%n",  "Tax (12%%):", tax);
        System.out.printf("%-14s %.2f%n",  "Net pay:",  net);

        input.close();
    }
}
